<script setup lang="ts">
import type {CommunityEntry} from '~/types/community'
const auth=useAuth(),{loginOpen}=useForum(),allowed=computed(()=>auth.user.value&&auth.user.value.role!=='member'),items=ref<CommunityEntry[]>([]),page=ref(1),total=ref(0),error=ref(''),success=ref(''),busy=ref(false),uploading=ref(false),editingId=ref('')
const empty=()=>({title:'',content:'',date:new Date().toLocaleDateString('sv-SE'),kind:'activity' as 'activity'|'moment',assetIds:[] as string[],status:'published' as 'published'|'hidden'})
const form=ref(empty())
async function load(){await auth.initialize();if(!allowed.value)return;try{const data=await auth.request<{items:CommunityEntry[],total:number}>(`/admin/community-entries?page=${page.value}`);items.value=data.items;total.value=data.total}catch(e){error.value=(e as Error).message}}
function edit(item:CommunityEntry){editingId.value=item.id;form.value={title:item.title,content:item.content,date:item.date,kind:item.kind,assetIds:[...item.assetIds],status:item.status};success.value=''}
async function save(){if(busy.value||uploading.value)return;busy.value=true;error.value='';try{await auth.request('/admin/community-entries'+(editingId.value?'/'+editingId.value:''),form.value,editingId.value?'PATCH':'POST');editingId.value='';form.value=empty();success.value='动态与相册已保存。';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(load);watch(page,load);watch(()=>auth.user.value?.id,load)
useSeoMeta({title:'动态与相册管理 · 澄之响',robots:'noindex,nofollow'})
</script>
<template><div class="experience-page"><header class="experience-heading"><div><p class="eyebrow">KEEP OUR MEMORIES</p><h1>动态与相册管理<span>。</span></h1></div><NuxtLink to="/community">查看公开档案</NuxtLink></header><template v-if="allowed"><form class="experience-card settings-form" @submit.prevent="save"><h2>{{ editingId?'编辑动态':'记录一次相遇' }}</h2><fieldset class="plain-fieldset" :disabled="busy"><label class="community-field">标题<input v-model="form.title" required minlength="2" maxlength="80" /></label><div class="field-pair"><label class="community-field">日期<input v-model="form.date" type="date" required /></label><label class="community-field">类型<select v-model="form.kind"><option value="activity">社团活动</option><option value="moment">社团动态</option></select></label></div><label class="community-field">内容<textarea v-model="form.content" required maxlength="4000" rows="5"></textarea></label><GalleryUploader v-model="form.assetIds" :disabled="busy" @busy="uploading=$event" /><label class="community-field">显示状态<select v-model="form.status"><option value="published">公开发布</option><option value="hidden">暂不公开</option></select></label><div class="field-pair"><button class="button primary" :disabled="busy||uploading">{{ busy?'保存中…':'保存动态' }}</button><button v-if="editingId" type="button" class="button secondary" @click="editingId='';form=empty()">取消编辑</button></div></fieldset></form><p v-if="success" class="form-success" role="status">{{ success }}</p><section class="experience-card"><h2>已记录的动态</h2><article v-for="item in items" :key="item.id" class="entry-admin-row"><div><strong>{{ item.title }}</strong><p>{{ item.date }} · {{ item.assetIds.length }} 张照片 · {{ item.status==='published'?'公开':'隐藏' }}</p></div><button class="text-link" :disabled="busy||uploading" @click="edit(item)">编辑</button></article><div class="page-controls"><button :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="page*12>=total" @click="page++">下一页</button></div></section></template><div v-else class="empty-state"><p>需要管理员账号。</p><button class="button primary" @click="loginOpen=true">登录</button></div><p v-if="error" class="form-error" role="alert">{{ error }}</p></div></template>
